              break;
            const token = await this.mintDownloadToken(item.exercise_id, f.id || null);
            lines.push(`\u{1F4CE} ${f.filename}: ${base.replace(/\/+$/, "")}/public/exercise-files/${item.exercise_id}?token=${token}`);
