          ext: true,
          fa: "NVLD \u0631\u062F \u0634\u062F\u0647 \u0627\u0633\u062A.",
          q: "\u0636\u0639\u0641 \u062F\u06CC\u062F\u0627\u0631\u06CC-\u0641\u0636\u0627\u06CC\u06CC \u062E\u0627\u0644\u0635 \u0627\u0633\u062A \u06CC\u0627 \u0628\u0627 \u062E\u0645\u06CC\u0631\u0645\u0627\u06CC\u0647\u0654 \u0627\u0631\u062A\u0628\u0627\u0637\u06CC \u0622\u0645\u06CC\u062E\u062A\u0647\u061F \u0627\u06AF\u0631 \u0645\u0634\u06A9\u0644 \u0627\u0635\u0644\u06CC \u062F\u0631 \u0631\u0627\u0628\u0637\u0647 \u0648 \u0631\u0641\u062A\u0627\u0631\u0647\u0627\u06CC \u062A\u06A9\u0631\u0627\u0631\u06CC \u0627\u0633\u062A\u060C \u0646\u0647 \u0634\u06A9\u0644 \u0648 \u0641\u0636\u0627\u060C \u0628\u0644\u0647 \u0628\u0632\u0646\u06CC\u062F."
