function resolveBattery(defs) {
  const byKey = new Map(defs.map((d) => [d.key, d]));
  return defs.map((d) => {
    if (!d.sameItemsAs)
      return d;
    const src = byKey.get(d.sameItemsAs);
    if (!src)
      throw new Error(`battery: sameItemsAs \u067E\u06CC\u062F\u0627 \u0646\u0634\u062F \u2014 ${d.key} \u2192 ${d.sameItemsAs}`);
    return { ...d, fields: src.fields };
  });
}
