  // ─── ASD ───
  autism: {
    nameFa: "\u0627\u062E\u062A\u0644\u0627\u0644 \u0637\u06CC\u0641 \u0627\u062A\u06CC\u0633\u0645",
    nameEn: "Autism Spectrum Disorder",
    icd: "F84.0",
    criteria: [
      { id: "autism.a1", group: "A", textFa: "\u06A9\u0645\u0628\u0648\u062F \u062F\u0631 \u062A\u0642\u0627\u0628\u0644 \u0627\u062C\u062A\u0645\u0627\u0639\u06CC-\u0647\u06CC\u062C\u0627\u0646\u06CC (\u062E\u0646\u062F\u0642 \u0645\u0634\u062A\u0631\u06A9\u060C \u0646\u0634\u0627\u0646\u200C\u062F\u0627\u062F\u0646\u060C \u0648\u0627\u06A9\u0646\u0634 \u0645\u062A\u0642\u0627\u0628\u0644)." },
      { id: "autism.a2", group: "A", textFa: "\u06A9\u0645\u0628\u0648\u062F \u062F\u0631 \u0631\u0641\u062A\u0627\u0631 \u0627\u0631\u062A\u0628\u0627\u0637\u06CC \u063A\u06CC\u0631\u06A9\u0644\u0627\u0645\u06CC (\u062A\u0645\u0627\u0633 \u0686\u0634\u0645\u06CC\u060C \u0627\u0634\u0627\u0631\u0647\u060C \u0632\u0628\u0627\u0646 \u0628\u062F\u0646)." },
      { id: "autism.a3", group: "A", textFa: "\u06A9\u0645\u0628\u0648\u062F \u062F\u0631 \u0634\u06A9\u0644\u200C\u062F\u0647\u06CC\u060C \u062D\u0641\u0638 \u0648 \u0641\u0647\u0645 \u0631\u0648\u0627\u0628\u0637 (\u062F\u0648\u0633\u062A\u06CC\u060C \u0646\u0648\u0628\u062A\u200C\u06AF\u06CC\u0631\u06CC\u060C \u062A\u0646\u0638\u06CC\u0645 \u0631\u0641\u062A\u0627\u0631 \u0627\u062C\u062A\u0645\u0627\u0639\u06CC)." },
      { id: "autism.b1", group: "B", textFa: "\u06AF\u0641\u062A\u0627\u0631/\u062D\u0631\u06A9\u062A/\u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0627\u0632 \u0627\u0634\u06CC\u0627 \u0628\u0647\u200C\u0635\u0648\u0631\u062A \u062A\u06A9\u0631\u0627\u0631\u06CC \u06CC\u0627 \u06CC\u06A9\u0646\u0648\u0627\u062E\u062A." },
      { id: "autism.b2", group: "B", textFa: "\u067E\u0627\u06CC\u0628\u0646\u062F\u06CC \u0627\u0641\u0631\u0627\u0637\u06CC \u0628\u0647 \u06CC\u06A9\u0646\u0648\u0627\u062E\u062A\u06CC\u060C \u0622\u06CC\u06CC\u0646\u200C\u0647\u0627 \u06CC\u0627 \u0645\u0642\u0627\u0648\u0645\u062A \u062F\u0631 \u0628\u0631\u0627\u0628\u0631 \u062A\u063A\u06CC\u06CC\u0631." },
      { id: "autism.b3", group: "B", textFa: "\u0639\u0644\u0627\u06CC\u0642 \u0634\u062F\u06CC\u062F\u060C \u0645\u062D\u062F\u0648\u062F \u0648 \u063A\u06CC\u0631\u0645\u0639\u0645\u0648\u0644." },
      { id: "autism.b4", group: "B", textFa: "\u0648\u0627\u06A9\u0646\u0634 \u0628\u06CC\u0634\u200C\u0627\u0632\u062D\u062F \u06CC\u0627 \u06A9\u0645\u200C\u062A\u0631 \u0627\u0632 \u062D\u062F \u0628\u0647 \u0645\u062D\u0631\u06A9 \u062D\u0633\u06CC \u06CC\u0627 \u0639\u0644\u0627\u0642\u0647\u0654 \u062F\u06CC\u062F\u0627\u0631\u06CC \u0628\u0647 \u0627\u062C\u0632\u0627\u06CC \u0627\u0634\u06CC\u0627." },
      { id: "autism.c", group: "C", textFa: "\u0646\u0634\u0627\u0646\u0647\u200C\u0647\u0627 \u0627\u0632 \u062F\u0648\u0631\u0647\u0654 \u0627\u0628\u062A\u062F\u0627\u06CC\u06CC \u0631\u0634\u062F \u0648\u062C\u0648\u062F \u062F\u0627\u0634\u062A\u0647 (\u062D\u062A\u06CC \u0627\u06AF\u0631 \u06A9\u0627\u0645\u0644 \u062A\u0627 \u0645\u0637\u0627\u0644\u0628\u0647\u0654 \u0627\u062C\u062A\u0645\u0627\u0639\u06CC \u0622\u0634\u06A9\u0627\u0631 \u0646\u0634\u062F\u0647 \u0628\u0627\u0634\u062F)." },
      { id: "autism.d", group: "D", textFa: "\u0646\u0634\u0627\u0646\u0647\u200C\u0647\u0627 \u0639\u0645\u0644\u06A9\u0631\u062F \u0631\u0648\u0632\u0627\u0646\u0647 \u0631\u0627 \u0645\u0644\u0645\u0648\u0633 \u0645\u062E\u062A\u0644 \u06A9\u0631\u062F\u0647\u200C\u0627\u0646\u062F." },
      { id: "autism.e", group: "E", textFa: "\u0628\u0647\u062A\u0631 \u0628\u0627 \u0646\u0627\u0631\u0633\u0627\u06CC\u06CC \u0641\u06A9\u0631\u06CC \u06CC\u0627 \u0627\u062E\u062A\u0644\u0627\u0644 \u0632\u0628\u0627\u0646\u06CC \u0628\u0647\u200C\u062A\u0646\u0647\u0627\u06CC\u06CC \u062A\u0648\u0636\u06CC\u062D \u062F\u0627\u062F\u0647 \u0646\u0634\u0648\u062F." }
    ],
    durationFa: "\u067E\u0627\u06CC\u062F\u0627\u0631 \u062F\u0631 \u0637\u0648\u0644 \u0631\u0634\u062F.",
    onsetFa: "\u0627\u0632 \u062F\u0648\u0631\u0647\u0654 \u0627\u0628\u062A\u062F\u0627\u06CC\u06CC \u0631\u0634\u062F.",
    exclusionsFa: ["\u0646\u0627\u0631\u0633\u0627\u06CC\u06CC \u0641\u06A9\u0631\u06CC \u0628\u0647\u200C\u062A\u0646\u0647\u0627\u06CC\u06CC", "\u0627\u062E\u062A\u0644\u0627\u0644 \u0632\u0628\u0627\u0646\u06CC \u0628\u0647\u200C\u062A\u0646\u0647\u0627\u06CC\u06CC"],
    referralFa: ["\u0627\u0631\u0632\u06CC\u0627\u0628\u06CC \u062A\u062E\u0635\u0635\u06CC \u0627\u062A\u06CC\u0633\u0645 \u0647\u0645\u06CC\u0634\u0647 \u062E\u0637 \u0642\u0631\u0645\u0632 \u0627\u0633\u062A \u2014 \u0686\u06A9\u200C\u0644\u06CC\u0633\u062A \u0641\u0642\u0637 \u063A\u0631\u0628\u0627\u0644 \u0627\u0633\u062A", "\u062F\u0631 \u0635\u0648\u0631\u062A \u0634\u06A9 \u0634\u0646\u0648\u0627\u06CC\u06CC: \u0627\u0631\u062C\u0627\u0639 \u0634\u0646\u0648\u0627\u06CC\u06CC\u200C\u0634\u0646\u0627\u0633"]
  },
