    coreDeficit: "\u0646\u0628\u0648\u062F\u0650 \u0631\u0648\u062A\u06CC\u0646 \u0648 \u0631\u0648\u0634 \u0645\u0637\u0627\u0644\u0639\u0647",
    homeSigns: [
      "\u0634\u0631\u0648\u0639 \u0645\u0637\u0627\u0644\u0639\u0647 \u0647\u0631 \u0631\u0648\u0632 \u0628\u0627 \u0686\u0627\u0646\u0647\u200C\u0632\u0646\u06CC \u0648 \u062A\u0623\u062E\u06CC\u0631 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062A\u061B \u0633\u0627\u0639\u062A \u06A9\u0627\u0631\u0634 \u0631\u0648\u0632\u0628\u0647\u200C\u0631\u0648\u0632 \u062C\u0627\u0628\u0647\u200C\u062C\u0627 \u0645\u06CC\u200C\u0634\u0648\u062F.",
      "\u0648\u0633\u0637 \u062A\u06A9\u0644\u06CC\u0641 \u0627\u0632 \u062C\u0627\u06CC \u062E\u0648\u062F \u0628\u0644\u0646\u062F \u0645\u06CC\u200C\u0634\u0648\u062F\u061B \u06AF\u0648\u0634\u06CC \u06CC\u0627 \u062A\u0644\u0648\u06CC\u0632\u06CC\u0648\u0646 \u062F\u0631 \u062F\u0633\u062A\u0631\u0633 \u0627\u0633\u062A."
    ],
    schoolSigns: [
      "\u062A\u06A9\u0644\u06CC\u0641\u200C\u0647\u0627\u06CC \u062E\u0627\u0646\u0647 \u0631\u0627 \u0646\u0627\u0642\u0635\u060C \u0646\u0627\u0645\u0631\u062A\u0628 \u06CC\u0627 \u0628\u0627 \u062A\u0623\u062E\u06CC\u0631 \u0645\u06CC\u200C\u0622\u0648\u0631\u062F.",
      "\u062F\u0631 \xAB\u0631\u0648\u0634 \u06A9\u0627\u0631\xBB \u0636\u0639\u06CC\u0641 \u0627\u0633\u062A: \u0627\u0632 \u06A9\u062C\u0627 \u0634\u0631\u0648\u0639 \u06A9\u0646\u062F \u0646\u0645\u06CC\u200C\u062F\u0627\u0646\u062F \u0648 \u06A9\u0644 \u0648\u0642\u062A \u0631\u0627 \u0631\u0648\u06CC \u06CC\u06A9 \u0633\u0624\u0627\u0644 \u0645\u06CC\u200C\u06AF\u0630\u0627\u0631\u062F."
    ],
    differentials: ["ADHD (\u0628\u06CC\u200C\u0646\u0638\u0645\u06CC \u0647\u0645\u0647\u200C\u062C\u0627 \u062D\u0627\u0636\u0631 \u062D\u062A\u06CC \u0628\u0627 \u0631\u0648\u062A\u06CC\u0646)", "\u0627\u0641\u062A \u0627\u0646\u06AF\u06CC\u0632\u0634\u06CC (\u062A\u06A9\u0644\u06CC\u0641 \u0627\u0635\u0644\u0627\u064B \u0634\u0631\u0648\u0639 \u0646\u0645\u06CC\u200C\u0634\u0648\u062F)"],
    instruments: [],
    probes: [],
    exercises: [
      { title: "\u0631\u0648\u062A\u06CC\u0646 \u0639\u0635\u0631\u0627\u0646\u0647\u0654 \u062B\u0627\u0628\u062A", description: "\u0633\u0627\u0639\u062A \u0648 \u062C\u0627\u06CC \u062B\u0627\u0628\u062A\u060C \u0628\u0631\u0646\u0627\u0645\u0647\u0654 \u062F\u06CC\u062F\u0627\u0631\u06CC \u0639\u0635\u0631\u0627\u0646\u0647\u061B \u0631\u0648\u062A\u06CC\u0646 \u062C\u0627\u06CC \u0627\u0646\u06AF\u06CC\u0632\u0647\u0654 \u062F\u0627\u0626\u0645\u06CC \u0631\u0627 \u0645\u06CC\u200C\u06AF\u06CC\u0631\u062F.", minutes: 5 },
      { title: "\u067E\u0648\u0645\u0648\u062F\u0648\u0631\u0648\u06CC \u06A9\u0648\u062F\u06A9", description: "\u06F1\u06F0-\u06F1\u06F5 \u062F\u0642\u06CC\u0642\u0647 \u06A9\u0627\u0631 + \u06F5 \u062F\u0642\u06CC\u0642\u0647 \u0628\u0627\u0632\u06CC\u061B \u0628\u0627\u0632\u0647\u200C\u0647\u0627 \u0628\u0627 \u062A\u0627\u06CC\u0645\u0631 \u0628\u0635\u0631\u06CC \u0645\u0634\u062E\u0635.", minutes: 25 },
      { title: "\u062A\u06A9\u0647\u200C\u062A\u06A9\u0647 \u06A9\u0631\u062F\u0646 \u062A\u06A9\u0644\u06CC\u0641", description: "\u062A\u06A9\u0644\u06CC\u0641 \u0628\u0647 \u0628\u062E\u0634\u200C\u0647\u0627\u06CC \u06A9\u0648\u0686\u06A9 \u062A\u0642\u0633\u06CC\u0645 \u0648 \u0628\u0647\u200C\u062A\u0631\u062A\u06CC\u0628 \u062A\u06CC\u06A9 \u0628\u062E\u0648\u0631\u062F.", minutes: 10 }
    ],
    path: STANDARD_PATH,
    texts: {
      saw: "\u0627\u0644\u06AF\u0648\u06CC \u0634\u0631\u0648\u0639 \u0686\u0627\u0646\u0647\u200C\u0632\u0646\u06CC \u0648 \u0646\u0628\u0648\u062F \u0631\u0648\u062A\u06CC\u0646 \u06AF\u0632\u0627\u0631\u0634 \u0634\u062F\u0647 \u0627\u0633\u062A.",
      means: "\u0645\u0634\u06A9\u0644 \u0631\u0648\u0634 \u0627\u0633\u062A\u060C \u0646\u0647 \u062A\u0648\u0627\u0646\u061B \u0628\u0631\u0646\u0627\u0645\u0647\u0654 \u062F\u06CC\u062F\u0627\u0631\u06CC \u0648 \u0628\u0627\u0632\u0647\u200C\u0647\u0627\u06CC \u06A9\u0648\u062A\u0627\u0647 \u0646\u0638\u0645 \u0631\u0627 \u062E\u0648\u062F\u06A9\u0627\u0631 \u0645\u06CC\u200C\u06A9\u0646\u062F.",
      next: "\u0631\u0648\u062A\u06CC\u0646 \u0631\u0627 \u0628\u0627 \u0647\u0645 \u0628\u0633\u0627\u0632\u06CC\u062F \u0648 \u062F\u0648 \u0647\u0641\u062A\u0647 \u0647\u0645\u0631\u0627\u0647\u06CC \u06A9\u0646\u06CC\u062F\u061B \u062D\u0630\u0641 \u0628\u0627\u0632\u06CC \u0628\u0631\u0627\u06CC \u062C\u0628\u0631\u0627\u0646 \u0645\u0645\u0646\u0648\u0639."
    }
