    title: "\u062A\u0648\u0627\u0646\u0628\u062E\u0634\u06CC \u062D\u0631\u06A9\u062A\u06CC-\u062C\u0633\u0645\u06CC",
    coreDeficit: "\u062D\u0631\u06A9\u062A \u062F\u0631\u0634\u062A/\u0638\u0631\u06CC\u0641\u060C \u062A\u0639\u0627\u062F\u0644 \u0648 \u0647\u0645\u0627\u0647\u0646\u06AF\u06CC",
    homeSigns: [
      "\u0645\u06A9\u0631\u0631 \u0645\u06CC\u200C\u0627\u0641\u062A\u062F\u060C \u0628\u0647 \u0644\u0628\u0647 \u0648 \u062F\u06CC\u0648\u0627\u0631 \u062A\u06A9\u06CC\u0647 \u0645\u06CC\u200C\u062F\u0647\u062F \u06CC\u0627 \u0627\u0632 \u0628\u0627\u0632\u06CC\u200C\u0647\u0627\u06CC \u062C\u0633\u0645\u0627\u0646\u06CC \u0641\u0631\u0627\u0631 \u0645\u06CC\u200C\u06A9\u0646\u062F.",
      "\u0642\u0644\u0645 \u0631\u0627 \u0646\u0627\u0645\u0646\u0627\u0633\u0628 \u0645\u06CC\u200C\u06AF\u06CC\u0631\u062F \u0648 \u0632\u0648\u062F \u0627\u0632 \u0646\u0648\u0634\u062A\u0646 \u062E\u0633\u062A\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F."
    ],
    schoolSigns: [
      "\u062F\u0631 \u0635\u0641\u060C \u0648\u0631\u0632\u0634 \u0648 \u06A9\u0627\u0631 \u0628\u0627 \u0648\u0633\u0627\u06CC\u0644 \u06A9\u0644\u0627\u0633 \u0647\u0645\u0627\u0647\u0646\u06AF\u06CC \u06A9\u0645\u062A\u0631 \u0627\u0632 \u0627\u0646\u062A\u0638\u0627\u0631 \u062F\u0627\u0631\u062F.",
      "\u0646\u0648\u0634\u062A\u0646\u0634 \u06A9\u0646\u062F \u0627\u0633\u062A \u0648 \u0638\u0627\u0647\u0631 \u0628\u0631\u06AF\u0647 \u0628\u0627 \u062A\u0644\u0627\u0634 \u0632\u06CC\u0627\u062F \u0647\u0645 \u0646\u0627\u067E\u0627\u06CC\u062F\u0627\u0631 \u0645\u06CC\u200C\u0645\u0627\u0646\u062F."
    ],
    differentials: ["\u0627\u062E\u062A\u0644\u0627\u0644 \u0647\u0645\u0627\u0647\u0646\u06AF\u06CC \u062D\u0631\u06A9\u062A\u06CC DCD (\u0628\u0627 DCDQ \u0648 \u0645\u0634\u0627\u0647\u062F\u0647)", "\u0636\u0639\u0641 \u062A\u0648\u0646 \u0639\u0636\u0644\u0627\u0646\u06CC \u2014 \u0627\u0631\u062C\u0627\u0639 \u067E\u0632\u0634\u06A9\u06CC \u062F\u0631 \u0635\u0648\u0631\u062A \u0634\u06A9"],
    instruments: ["ce-rehab-motor-v1"],
    probes: [],
    exercises: [
      { title: "\u0645\u0633\u06CC\u0631 \u0645\u0627\u0646\u0639 \u062E\u0627\u0646\u0647", description: "\u0631\u0648\u0634\u0646/\u062E\u0627\u0645\u0648\u0634\u060C \u067E\u0631\u06CC\u062F\u0646 \u0627\u0632 \u062E\u0637\u060C \u0631\u0627\u0647 \u0631\u0641\u062A\u0646 \u0631\u0648\u06CC \u062E\u0637\u200C\u0686\u06CC\u0646\u061B \u0631\u0648\u0632\u06CC \u06F1\u06F0 \u062F\u0642\u06CC\u0642\u0647 \u0628\u0627\u0632\u06CC\u200C\u0648\u0627\u0631.", minutes: 10 },
      { title: "\u06A9\u0627\u0631 \u0628\u0627 \u0627\u0646\u06AF\u0634\u062A\u0627\u0646", description: "\u0645\u0647\u0631\u0647\u060C \u062E\u0645\u06CC\u0631\u060C \u0628\u0631\u06CC\u062F\u0646 \u062E\u0637\u200C\u0647\u0627\u06CC \u0636\u062E\u06CC\u0645\u061B \u062F\u0633\u062A\u200C\u0647\u0627 \u0631\u0627 \u0628\u0631\u0627\u06CC \u0646\u0648\u0634\u062A\u0646 \u0622\u0645\u0627\u062F\u0647 \u0645\u06CC\u200C\u06A9\u0646\u062F.", minutes: 10 },
      { title: "\u0628\u0627\u0632\u06CC \u062A\u0648\u067E \u062F\u0648\u0637\u0631\u0641\u0647", description: "\u067E\u0631\u062A\u0627\u0628 \u0648 \u06AF\u0631\u0641\u062A\u0646 \u0627\u0632 \u0641\u0627\u0635\u0644\u0647\u0654 \u0646\u0632\u062F\u06CC\u06A9 \u0648 \u06A9\u0645\u200C\u06A9\u0645 \u062F\u0648\u0631\u062A\u0631\u061B \u0647\u0645\u0627\u0647\u0646\u06AF\u06CC \u0686\u0634\u0645-\u062F\u0633\u062A.", minutes: 7 }
    ],
    path: REHAB_PATH,
    texts: {
      saw: "\u0627\u0631\u0632\u06CC\u0627\u0628\u06CC \u062D\u0631\u06A9\u062A\u06CC-\u062C\u0633\u0645\u06CC (\u062F\u0631\u0634\u062A/\u0638\u0631\u06CC\u0641/\u062A\u0639\u0627\u062F\u0644/\u0686\u0634\u0645-\u062F\u0633\u062A) \u062B\u0628\u062A \u0634\u062F\u0647 \u0627\u0633\u062A.",
      means: "\u062D\u0631\u06A9\u062A \u0628\u0627 \u062A\u0645\u0631\u06CC\u0646 \u062A\u06A9\u0631\u0627\u0631\u067E\u0630\u06CC\u0631 \u0648 \u0644\u0630\u062A\u200C\u0628\u062E\u0634 \u0633\u0627\u062E\u062A\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F\u061B \u062C\u0644\u0633\u0627\u062A \u0641\u0631\u062F\u06CC\u060C \u067E\u0627\u06CC\u0647 \u0648 \u0628\u0627\u0632\u06CC \u06AF\u0631\u0648\u0647\u06CC\u060C \u0627\u0646\u06AF\u06CC\u0632\u0647 \u0645\u06CC\u200C\u0633\u0627\u0632\u062F.",
      next: "\u0627\u0647\u062F\u0627\u0641 \u062D\u0631\u06A9\u062A\u06CC \u06A9\u0648\u0686\u06A9 \u0647\u0641\u062A\u06AF\u06CC \u0628\u0686\u06CC\u0646\u06CC\u062F \u0648 \u067E\u06CC\u0634\u0631\u0641\u062A \u0631\u0627 \u062F\u0631 \u062C\u0644\u0633\u0627\u062A \u0645\u062F\u0627\u062E\u0644\u0647 \u062B\u0628\u062A \u06A9\u0646\u06CC\u062F."
    }
